class CartItem { final String productId,name,image,unit; final double price; final int quantity; const CartItem({required this.productId,required this.name,this.image='',required this.price,required this.quantity,this.unit='' }); factory CartItem.fromMap(Map<String,dynamic> m)=>CartItem(productId:m['productId'],name:m['name'],image:m['image']??'',price:(m['price']??0).toDouble(),quantity:m['quantity']??1,unit:m['unit']??''); Map<String,dynamic> toMap()=>{'productId':productId,'name':name,'image':image,'price':price,'quantity':quantity,'unit':unit}; }
